    public static final class Attachments {

        /**
         * Holds additional loot tables that will be dropped by the entity when it is killed.
         */
        public static final AttachmentType<BonusLootTables> BONUS_LOOT_TABLES = R.attachment("bonus_loot_tables", () -> BonusLootTables.EMPTY,
            b -> b.serialize(BonusLootTables.CODEC.fieldOf("tables"), blt -> !blt.tables().isEmpty()));

        /**
         * Holds additional (pre-mitigation) damage reduction values for a given entity.
         */
        public static final AttachmentType<DamageReductions> DAMAGE_REDUCTIONS = R.attachment("damage_reductions", () -> DamageReductions.EMPTY, b -> b.serialize(DamageReductions.CODEC.fieldOf("reductions"), dr -> !dr.isEmpty()));

        /**
         * The player's current {@link WorldTier}.
         */
        public static final AttachmentType<WorldTier> WORLD_TIER = R.attachment("world_tier", () -> WorldTier.HAVEN, b -> b.serialize(WorldTier.CODEC.fieldOf("tier")).copyOnDeath().copyHandler((t, holder, prov) -> t));

        /**
         * Records if the {@link TierAugment}s for the current world tier have been applied to the attached entity or not.
         * <p>
         * If this is not set, they will be applied the next time the entity joins the level.
         */
        public static final AttachmentType<Boolean> TIER_AUGMENTS_APPLIED = R.attachment("tier_augments_applied", () -> false, b -> b.serialize(Codec.BOOL.fieldOf("applied")));

        /**
         * Supports the {@link FrozenDropsBonus} by recording the amount of post-mitigation cold damage an entity has taken.
         */
        public static final AttachmentType<Float> COLD_DAMAGE_TAKEN = R.attachment("cold_damage_taken", () -> 0F, b -> b.serialize(Codec.FLOAT.fieldOf("damage")));

        /**
         * Stores the game time at which the player may next trigger a natural invader spawn.
         * <p>
         * When an invader spawns, this is set for the triggering player and all same-tier players within
         * the boss announcement range. A value of zero (or any time in the past) means no cooldown is active.
         */
        public static final AttachmentType<Long> INVADER_COOLDOWN = R.attachment("invader_cooldown", () -> 0L, b -> b.serialize(Codec.LONG.fieldOf("time"), t -> t != 0L).copyOnDeath());

        /**
         * Supports the {@link AntiGravityArrowBonus} by recording the game time at which an arrow had its gravity disabled.
         * <p>
         * Only present on arrows that are currently flying without gravity. Removed once gravity is restored.
         */
        public static final AttachmentType<Long> ANTI_GRAVITY_ARROW_START = R.attachment("anti_gravity_arrow_start", () -> 0L, b -> b.serialize(Codec.LONG.fieldOf("start")));

        /**
         * Client-only attachment to record if the affix effect render has started.
         * <p>
         * Rendering starts when an item touches the ground, and stops if it leaves the ground.
         */
        public static final AttachmentType<Boolean> AFFIX_EFFECT_RENDER_STARTED = R.attachment("affix_effect_render_started", () -> false, UnaryOperator.identity());

        /**
         * Client-only attachment to record the tick count of an entity when the effect renderer starts.
         * <p>
         * This is used to interpolate progress-based effects that ease in.
         */
        public static final AttachmentType<Integer> AFFIX_EFFECT_START_TIME = R.attachment("affix_effect_start_time", () -> 0, UnaryOperator.identity());

        /**
         * Client-only attachment to record the time (in ticks, relative to the entity tick count) at which the next affix effect particle spawns.
         */
        public static final AttachmentType<Integer> AFFIX_EFFECT_NEXT_PARTICLE_TIME = R.attachment("affix_effect_next_particle_time", () -> 0, UnaryOperator.identity());

        /**
         * Holds the set of attributes whose bonuses the player has chosen to suppress via an {@link AttributeToggleAffix}.
         */
        public static final AttachmentType<AttributeToggles> ATTRIBUTE_TOGGLES = R.attachment("attribute_toggles", () -> AttributeToggles.EMPTY, b -> b.serialize(AttributeToggles.CODEC.fieldOf("attributes"), t -> !t.isEmpty()).copyOnDeath());

        public static final AttachmentType<RadialState> RADIAL_MINING_MODE = R.attachment("radial_mining_mode", () -> RadialState.REQUIRE_NOT_SNEAKING, b -> b.serialize(RadialState.CODEC.fieldOf("mode")).copyOnDeath());

        private static void bootstrap() {}
    }

