/**
 * An affix is a construct very similar to an enchantment, providing bonuses to arbitrary items.
 * The Affix's Level is a float from 0 to 1 that defines its relative power level, compared to max.
 * What the level means is up to the individual affix.
 */
public abstract class Affix implements CodecProvider<Affix>, Weighted {

    public static final float MAX_LEVEL = 2.0F;
    public static final float STANDARD_MAX_LEVEL = 1.0F;

    protected final AffixDefinition definition;

    protected Affix(AffixDefinition definition) {
        this.definition = definition;
    }

    /**
     * Checks if this affix can be applied to an item.
     *
     * @param stack  The item being checked against.
     * @param cat    The category of the target item.
     * @param rarity The rarity of the target item.
     * @return If this affix can be applied to the item at the specified rarity.
     */
    public abstract boolean canApplyTo(ItemStack stack, LootCategory cat, LootRarity rarity);

    /**
     * Gets the one-line description for this affix, to be added to the item stack's tooltip.
     * <p>
     * Description tooltips are added immediately before enchantment tooltips, or after the name if none are present.
     * If you do not want to show a specific affix description, return {@link Component#empty()}.
     *
     * @param inst The affix instance.
     */
    public MutableComponent getDescription(AffixInstance inst, AttributeTooltipContext ctx) {
        return Component.translatable("affix." + this.id() + ".desc", fmt(inst.level()));
    }

    /**
     * Get a component representing an addition of this affix to the item's name.
     *
     * @return The name part, prefix or suffix, as requested.
     */
    public Component getName(boolean prefix) {
        if (prefix) {
            return Component.translatable("affix." + this.id());
        }
        return Component.translatable("affix." + this.id() + ".suffix");
    }

    /**
     * Returns a component containing the text shown in the Augmenting Table.
     * <p>
     * This text should show the current affix power, as well as the min/max power bounds, displaying to the user what the full range is.
     *
     * @param inst The affix instance.
     */
    public Component getAugmentingText(AffixInstance inst, AttributeTooltipContext ctx) {
        return this.getDescription(inst, ctx);
    }

    /**
     * Returns true if this affix is level-independent, meaning that its power does not change with the level of the affix.
     */
    public boolean isLevelIndependent(AffixInstance inst) {
        return false;
    }

    /**
     * Adds any attribute modifiers supplied by this affix to the passed consumer.
     * <p>
     * Attribute modifiers must have unique IDs per-slot, since the same affix may be applicable to multiple items.
     *
     * @param inst  The affix instance.
     * @param event The attribute modifiers event.
     */
    public void addModifiers(AffixInstance inst, StackAttributeModifiersEvent event) {}

    /**
     * Calculates the protection value of this affix, with respect to the given damage source.<br>
     * Math is in {@link CombatRules#getDamageAfterMagicAbsorb}<br>
     * Apothic Enchanting overrides that logic via its EnchHooks ASM hooks.<br>
     *
     * @param inst   The affix instance.
     * @param source The damage source to compare against.
     * @return How many protection points this affix is worth against this source.
     */
    public float getDamageProtection(AffixInstance inst, DamageSource source) {
        return 0;
    }

    /**
     * Calculates the additional damage this affix deals.
     * This damage is dealt as player physical damage, and is not impacted by critical strikes.
     *
     * @param inst   The affix instance.
     * @param entity The target entity.
     */
    public float getDamageBonus(AffixInstance inst, Entity entity) {
        return 0.0F;
    }

    /**
     * Called when someone attacks an entity with an item containing this affix.
     * More specifically, this is invoked whenever the user attacks a target, while having an item with this affix in either hand or any armor slot.
     *
     * @param inst   The affix instance.
     * @param user   The wielder of the weapon. The weapon stack will be in their main hand.
     * @param target The target entity being attacked.
     */
    public void doPostAttack(AffixInstance inst, LivingEntity user, Entity target) {}

    /**
     * Whenever an entity that has this affix on one of its associated items is damaged this method will be
     * called.
     */
    public void doPostHurt(AffixInstance inst, LivingEntity user, DamageSource source) {}

    /**
     * Called when a user fires an projectile from a weapon with this affix on it.
     */
    public void onProjectileFired(AffixInstance inst, LivingEntity user, Projectile projectile) {}

    /**
     * Called when {@link Item#useOn(ItemUseContext)} would be called for an item with this affix.
     * Return null to not impact the original result type.
     */
    @Nullable
    public InteractionResult onItemUse(AffixInstance inst, UseOnContext ctx) {
        return null;
    }

    /**
     * Called when an projectile that was marked with this affix hits a target.
     */
    public void onProjectileImpact(float level, LootRarity rarity, Projectile proj, HitResult res, HitResult.Type type) {}

    /**
     * Called when a shield with this affix blocks some amount of damage.
     *
     * @param entity The blocking entity.
     * @param source The damage source being blocked.
     * @param amount The amount of damage blocked.
     * @param level  The level of this affix.
     * @return The amount of damage that is *actually* blocked by the shield, after this affix applies.
     */
    public float onShieldBlock(AffixInstance inst, LivingEntity entity, DamageSource source, float amount) {
        return amount;
    }

    /**
     * Called when a player with this affix breaks a block.
     *
     * @param player The breaking player.
     * @param world  The level the block was broken in.
     * @param pos    The position of the block.
     * @param state  The state that was broken.
     */
    public void onBlockBreak(AffixInstance inst, Player player, LevelAccessor world, BlockPos pos, BlockState state) {

    }

    /**
     * Allows an affix to reduce durability damage to an item.
     *
     * @param stack  The stack with the affix.
     * @param rarity The rarity of the item.
     * @param level  The level of the affix.
     * @param user   The user of the item, if applicable.
     * @return The percentage [0, 1] of durability damage to ignore. This value will be summed with all other affixes that increase it.
     */
    public float getDurabilityBonusPercentage(AffixInstance inst) {
        return 0;
    }

    /**
     * Fires during the {@link LivingHurtEvent}, and allows for modification of the damage value.<br>
     * If the value is set to zero or below, the event will be cancelled.
     *
     * @param stack  The stack with the affix.
     * @param rarity The rarity of the item.
     * @param level  The level of the affix.
     * @param src    The Damage Source of the attack.
     * @param ent    The entity being attacked.
     * @param amount The amount of damage that is to be taken.
     * @return The amount of damage that will be taken, after modification. This value will propagate to other affixes.
     */
    public float onHurt(AffixInstance inst, DamageSource src, LivingEntity ent, float amount) {
        return amount;
    }

    /**
     * Returns true if this affix enables telepathy.
     */
    public boolean enablesTelepathy() {
        return false;
    }

    /**
     * Fires during {@link GetEnchantmentLevelEvent} and allows for increasing enchantment levels.
     *
     * @param inst  The affix instance.
     * @param event The GetEnchantmentLevelEvent, which allows for modification of the levels.
     */
    public void getEnchantmentLevels(AffixInstance inst, GetEnchantmentLevelEvent event) {}

    /**
     * Fires from {@link LootModifier#apply(ObjectArrayList, LootContext)} when this affix is on the tool given by the context.
     *
     * @param stack  The stack with the affix.
     * @param rarity The rarity of the item.
     * @param level  The level of the affix.
     * @param loot   The generated loot.
     * @param ctx    The loot context.
     */
    public void modifyLoot(AffixInstance inst, ObjectArrayList<ItemStack> loot, LootContext ctx) {}

    /**
     * Generic {@link LivingDropsEvent} handler which allows affixes to execute custom functionality.
     */
    public void modifyEntityLoot(AffixInstance inst, LivingDropsEvent event) {}

    /**
     * An affix is compatible with another affix if they aren't the name affix, and neither is exclusive with the other.
     */
    public boolean isCompatibleWith(Affix affix) {
        return this != affix && !this.definition().exclusiveSet().contains(AffixRegistry.INSTANCE.holder(affix)) && !affix.definition().exclusiveSet().contains(AffixRegistry.INSTANCE.holder(this));
    }

    public boolean isCompatibleWith(ItemAffixes affixes) {
        return affixes.liveAffixes().allMatch(this::isCompatibleWith);
    }

    @Override
    public String toString() {
        return String.format("Affix: %s", this.id());
    }

    public final AffixDefinition definition() {
        return this.definition;
    }

    @Override
    public final TieredWeights weights() {
        return this.definition.weights();
    }

    public final Identifier id() {
        return AffixRegistry.INSTANCE.getKey(this);
    }

    public static String fmt(float f) {
        if (f == (long) f) {
            return String.format("%d", (long) f);
        }
        else {
            return IAttributeExtension.FORMAT.format(f);
        }
    }

    public static MutableComponent valueBounds(Component min, Component max) {
        return CommonComponents.space().append(Component.translatable("misc.apotheosis.affix_bounds", min, max).withStyle(ChatFormatting.DARK_GRAY));
    }

    /**
     * Generates a deterministic {@link Identifier} that is unique for a given socketed gem instance.
     * <p>
     * Can be used to generate attribute modifiers, track cooldowns, and other things that need to be unique per-gem-in-slot.
     *
     * @param inst The owning gem instance for the bonus
     * @param salt A salt value, which can be used if the bonus needs multiple modifiers.
     */
    static Identifier makeUniqueId(AffixInstance inst, String salt) {
        Identifier key = inst.affix().getId();
        LootCategory cat = LootCategory.forItem(inst.stack());
        return Identifier.fromNamespaceAndPath(key.getNamespace(), key.getPath() + "_modifier_" + cat.getSlots().id().toShortLanguageKey() + "_" + salt);
    }

    /**
     * Calls {@link #makeUniqueId(GemInstance, String)} with an empty salt value.
     */
    static Identifier makeUniqueId(AffixInstance inst) {
        return makeUniqueId(inst, "");
    }

    protected static <T extends Affix> App<RecordCodecBuilder.Mu<T>, AffixDefinition> affixDef() {
        return AffixDefinition.CODEC.fieldOf("definition").forGetter(Affix::definition);
    }
}

package dev.shadowsoffire.apotheosis.affix;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Stream;

import javax.annotation.Nullable;

import dev.shadowsoffire.apotheosis.Apoth.Components;
import dev.shadowsoffire.apotheosis.Apotheosis;
import dev.shadowsoffire.apotheosis.affix.reforging.ReforgingMenu;
import dev.shadowsoffire.apotheosis.loot.LootCategory;
import dev.shadowsoffire.apotheosis.loot.LootRarity;
import dev.shadowsoffire.apotheosis.loot.RarityRegistry;
import dev.shadowsoffire.apotheosis.mixin.ItemStackMixin;
import dev.shadowsoffire.apotheosis.tiers.WorldTier;
import dev.shadowsoffire.apothic_attributes.ApothicAttributes;
import dev.shadowsoffire.placebo.dynreg.DynamicHolder;
import dev.shadowsoffire.placebo.util.CachedObject;
import dev.shadowsoffire.placebo.util.CachedObject.CachedObjectSource;
import net.minecraft.ChatFormatting;
import net.minecraft.client.Minecraft;
import net.minecraft.client.player.LocalPlayer;
import net.minecraft.nbt.NbtOps;
import net.minecraft.nbt.Tag;
import net.minecraft.network.chat.Component;
import net.minecraft.network.chat.HoverEvent;
import net.minecraft.network.chat.MutableComponent;
import net.minecraft.network.chat.Style;
import net.minecraft.network.chat.contents.TranslatableContents;
import net.minecraft.resources.Identifier;
import net.minecraft.util.RandomSource;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.entity.projectile.Projectile;
import net.minecraft.world.item.Item.TooltipContext;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.component.ItemContainerContents;
import net.minecraft.world.item.component.TooltipDisplay;
import net.minecraft.world.level.levelgen.SingleThreadedRandomSource;
import net.neoforged.fml.loading.FMLEnvironment;
import net.neoforged.neoforge.common.util.AttributeTooltipContext;

public class AffixHelper {

    public static final Identifier AFFIX_CACHED_OBJECT = Apotheosis.loc("affixes");

    // Used to encode the shooting weapon on arrows.
    public static final String SOURCE_WEAPON = "apoth.source_weapon";

    /**
     * The level that the Sigil of Malice raises an affix to.
     */
    public static final float MALICE_LEVEL = Affix.MAX_LEVEL;

    /**
     * The chance that the Sigil of Malice will not reset another affix when only one affix below {@link #MALICE_LEVEL} remains.
     */
    public static final float FINAL_MALICE_CHANCE = 0.033F;

    /**
     * Adds this specific affix to the Item's NBT tag.
     */
    public static void applyAffix(ItemStack stack, AffixInstance inst) {
        ItemAffixes.Builder builder = stack.getOrDefault(Components.AFFIXES, ItemAffixes.EMPTY).toBuilder();
        builder.put(inst.affix(), inst.level());
        setAffixes(stack, builder.build());
    }

    public static void setAffixes(ItemStack stack, ItemAffixes affixes) {
        stack.set(Components.AFFIXES, affixes);
    }

    public static void setName(ItemStack stack, Component name) {
        stack.set(Components.AFFIX_NAME, name.copy());
    }

    @Nullable
    public static Component getName(ItemStack stack) {
        return stack.get(Components.AFFIX_NAME);
    }

    /**
     * Called from {@link ItemStackMixin} to update the {@link ItemStack#getHoverName() hover name} of an itemstack based on {@link Components#AFFIX_NAME}.
     * <p>
     * This method retrieves the current affix name, and if present, makes a deep copy of the contents to insert the hover name in as an argument.
     * <p>
     * Failure to make a deep copy of the contents will lead to the component being different on the client and server, causing desyncs in container menus.
     *
     * @param stack       The item stack
     * @param currentName The current return value from {@link ItemStack#getHoverName()}
     * @return The updated name, or null if the component was absent or malformed
     */
    @Nullable
    public static Component getModifiedStackName(ItemStack stack, Component currentName) {
        if (stack.has(Components.AFFIX_NAME)) {
            if (FMLEnvironment.getDist().isClient()) {
                Component hidden = ClientAccess.getHiddenAffixName(currentName);
                if (hidden != null) {
                    return hidden;
                }
            }

            try {
                Component component = AffixHelper.getName(stack);
                TranslatableContents contents = copyContents(component);
                int idx = "misc.apotheosis.affix_name.four".equals(contents.getKey()) ? 2 : 1;
                contents.getArgs()[idx] = currentName;
                var ret = MutableComponent.create(contents).withStyle(component.getStyle());
                for (Component sibling : component.getSiblings()) {
                    ret.append(sibling);
                }
                return ret;
            }
            catch (Exception exception) {
                stack.remove(Components.AFFIX_NAME);
            }
        }
        return null;
    }

    /**
     * Gets the affixes of an item. The returned map is immutable.
     * <p>
     * Due to potential reloads, it is possible for an affix instance to become unbound but still remain cached.
     *
     * @param stack The stack being queried.
     * @return An immutable map of all affixes on the stack, or an empty map if none were found.
     * @apiNote Prefer using {@link #streamAffixes(ItemStack)} where applicable, since invalid instances will be pre-filtered.
     */
    public static Map<DynamicHolder<Affix>, AffixInstance> getAffixes(ItemStack stack) {
        if (AffixRegistry.INSTANCE.getValues().isEmpty()) {
            return Collections.emptyMap(); // Don't enter getAffixesImpl if the affixes haven't loaded yet.
        }
        return CachedObjectSource.getOrCreate(stack, AFFIX_CACHED_OBJECT, AffixHelper::getAffixesImpl, CachedObject.hashComponents(Components.AFFIXES, Components.RARITY));
    }

    public static Map<DynamicHolder<Affix>, AffixInstance> getAffixesImpl(ItemStack stack) {
        if (stack.isEmpty()) {
            return Collections.emptyMap();
        }
        DynamicHolder<LootRarity> rarity = getRarity(stack);
        if (!rarity.isBound()) {
            return Collections.emptyMap();
        }
        Map<DynamicHolder<Affix>, AffixInstance> map = new HashMap<>();
        ItemAffixes affixes = stack.getOrDefault(Components.AFFIXES, ItemAffixes.EMPTY);
        if (!affixes.isEmpty()) {
            LootCategory cat = LootCategory.forItem(stack);
            for (DynamicHolder<Affix> affix : affixes.keySet()) {
                if (!affix.isBound() || !affix.get().canApplyTo(stack, cat, rarity.get())) {
                    continue;
                }
                float lvl = affixes.getLevel(affix);
                map.put(affix, new AffixInstance(affix, lvl, rarity, stack));
            }
        }
        return Collections.unmodifiableMap(map);
    }

    public static Stream<AffixInstance> streamAffixes(ItemStack stack) {
        return getAffixes(stack).values().stream().filter(AffixInstance::isValid);
    }

    public static Stream<AffixInstance> streamAffixes(Projectile proj) {
        return getAffixes(proj).values().stream().filter(AffixInstance::isValid);
    }

    public static boolean hasAffixes(ItemStack stack) {
        return !getAffixes(stack).isEmpty();
    }

    public static void setRarity(ItemStack stack, LootRarity rarity) {
        stack.set(Components.RARITY, RarityRegistry.INSTANCE.holder(rarity));
    }

    /**
     * Copies the entire source weapon itemstack into the target entity iff relevant components are present.
     *
     * @param stack  The source item stack (the ranged weapon that fired the projectile).
     * @param entity The newly created projectile.
     */
    public static void copyToProjectile(ItemStack stack, Entity entity) {
        ItemAffixes affixes = stack.getOrDefault(Components.AFFIXES, ItemAffixes.EMPTY);
        ItemContainerContents gems = stack.getOrDefault(Components.SOCKETED_GEMS, ItemContainerContents.EMPTY);
        if (!affixes.isEmpty() || gems.nonEmptyItemCopyStream().findAny().isPresent()) {
            Tag tag = ItemStack.CODEC.encodeStart(entity.level().registryAccess().createSerializationContext(NbtOps.INSTANCE), stack).getOrThrow();
            entity.getPersistentData().put(SOURCE_WEAPON, tag);
        }
    }

    /**
     * Retrieves the encoded source weapon from a projectile, if one was available.
     */
    public static ItemStack getSourceWeapon(Entity entity) {
        if (entity.getPersistentData().contains(SOURCE_WEAPON)) {
            return entity.getPersistentData().getCompound(SOURCE_WEAPON)
                .flatMap(t -> ItemStack.CODEC.parse(entity.level().registryAccess().createSerializationContext(NbtOps.INSTANCE), t).result())
                .orElse(ItemStack.EMPTY);
        }
        return ItemStack.EMPTY;
    }

    public static Map<DynamicHolder<Affix>, AffixInstance> getAffixes(Projectile proj) {
        ItemStack stack = getSourceWeapon(proj);
        return getAffixes(stack);
    }

    /**
     * May be unbound
     */
    public static DynamicHolder<LootRarity> getRarity(ItemStack stack) {
        return stack.getOrDefault(Components.RARITY, RarityRegistry.INSTANCE.emptyHolder());
    }

    public static Collection<DynamicHolder<Affix>> byType(AffixType type) {
        return AffixRegistry.INSTANCE.getTypeMap().get(type);
    }

    /**
     * Returns true if the Sigil of Malice can be applied to the given item stack.
     * <p>
     * Malice requires at least two level-dependent affixes, and cannot be applied if all level-dependent affixes are already at {@link #MALICE_LEVEL}.
     */
    public static boolean canApplyMalice(ItemStack stack) {
        return canApplyMalice(getMaliceTargets(stack));
    }

    /**
     * Returns true if the given item stack has at least one level-dependent affix, and all level-dependent affixes are at {@link #MALICE_LEVEL}.
     * <p>
     * An item in this state can no longer benefit from the Sigil of Malice.
     */
    public static boolean isExtremelyMalicious(ItemStack stack) {
        return isExtremelyMalicious(getMaliceTargets(stack));
    }

    /**
     * @see #canApplyMalice(ItemStack)
     */
    private static boolean canApplyMalice(List<AffixInstance> targets) {
        return targets.size() >= 2 && !isExtremelyMalicious(targets);
    }

    /**
     * @see #isExtremelyMalicious(ItemStack)
     */
    private static boolean isExtremelyMalicious(List<AffixInstance> targets) {
        return !targets.isEmpty() && targets.stream().allMatch(i -> i.level() >= MALICE_LEVEL);
    }

    /**
     * Returns all valid, level-dependent affixes on the item, which are the only affixes that the Sigil of Malice will interact with.
     */
    private static List<AffixInstance> getMaliceTargets(ItemStack stack) {
        List<AffixInstance> list = new ArrayList<>(AffixHelper.getAffixes(stack).values());
        list.removeIf(i -> !i.isValid() || i.isLevelIndependent());
        return list;
    }

    /**
     * Applies the effect of the Sigil of Malice to the given item stack.
     * <p>
     * The sigil increases the effective level of one affix on the item to {@link #MALICE_LEVEL}, and resets another affix at random (based on the reforge seed).
     * <p>
     * If only one affix below {@link #MALICE_LEVEL} remains, it is always the one upgraded. In that case, there is a {@link #FINAL_MALICE_CHANCE} chance that
     * nothing is reset,
     * leaving the item {@link #isExtremelyMalicious(ItemStack) extremely malicious}. Otherwise, one of the other affixes is reset as usual.
     * <p>
     * Does nothing if {@link #canApplyMalice(ItemStack)} is false.
     *
     * @param stack The input stack. The stack is modified in place.
     * @apiNote This cannot be run reliably on the client, as the reforge seed is not guaranteed to be present.
     */
    public static void applyMalice(Player player, ItemStack stack) {
        List<AffixInstance> afxList = getMaliceTargets(stack);
        if (!canApplyMalice(afxList)) {
            return;
        }

        int seed = player.getPersistentData().getIntOr(ReforgingMenu.REFORGE_SEED, 0);
        RandomSource rand = new SingleThreadedRandomSource(seed);

        ItemAffixes.Builder builder = stack.getOrDefault(Components.AFFIXES, ItemAffixes.EMPTY).toBuilder();

        AffixInstance buffed;
        AffixInstance reset = null;

        List<AffixInstance> upgradable = afxList.stream().filter(i -> i.level() < MALICE_LEVEL).toList();
        if (upgradable.size() == 1) {
            // Only one affix can still be upgraded. It is always upgraded, but there is only a 1/3 chance that nothing else is consumed.
            buffed = upgradable.getFirst();
            if (rand.nextFloat() >= FINAL_MALICE_CHANCE) {
                List<AffixInstance> others = new ArrayList<>(afxList);
                others.remove(buffed);
                reset = others.get(rand.nextInt(others.size()));
            }
        }
        else {
            // Choose two distinct indices
            int size = afxList.size();
            int firstIndex = rand.nextInt(size);
            int secondIndex;
            do {
                secondIndex = rand.nextInt(size);
            }
            while (secondIndex == firstIndex);

            buffed = afxList.get(firstIndex);
            reset = afxList.get(secondIndex);
        }

        builder.upgrade(buffed.affix(), MALICE_LEVEL);
        if (reset != null) {
            builder.put(reset.affix(), 0);
        }

        setAffixes(stack, builder.build());
        stack.set(Components.TOUCHED_BY_MALICE, stack.getOrDefault(Components.TOUCHED_BY_MALICE, 0) + 1);
        player.getPersistentData().putInt(ReforgingMenu.REFORGE_SEED, player.getRandom().nextInt());

        AttributeTooltipContext ctx = AttributeTooltipContext.of(player, TooltipContext.of(player.level()), TooltipDisplay.DEFAULT, ApothicAttributes.getTooltipFlag());

        AffixInstance buff = new AffixInstance(buffed.affix(), MALICE_LEVEL, getRarity(stack), stack);
        MutableComponent buffedName = Component.translatable("[%s]", buff.getName(true));
        buffedName.setStyle(Style.EMPTY.withColor(ChatFormatting.YELLOW).withHoverEvent(new HoverEvent.ShowText(buff.getAugmentingText(ctx))));

        Component msg;
        if (reset == null) {
            msg = Apotheosis.lang("text", "malice_notice_final", buffedName);
        }
        else {
            MutableComponent removedName = Component.translatable("[%s]", reset.getName(true));
            removedName.setStyle(Style.EMPTY.withColor(ChatFormatting.RED).withHoverEvent(new HoverEvent.ShowText(reset.getAugmentingText(ctx))));
            msg = Apotheosis.lang("text", "malice_notice", buffedName, removedName);
        }
        player.sendSystemMessage(msg);
    }

    /**
     * Applies the effect of the Sigil of Supremacy to the given item stack.
     * <p>
     * The sigil increases the effective level of all affixes on the item to 1.5F.
     *
     * @param stack The input stack. The stack is modified in place.
     */
    public static void applySupremacy(ItemStack stack) {
        ItemAffixes affixes = stack.getOrDefault(Components.AFFIXES, ItemAffixes.EMPTY);
        if (affixes.isEmpty()) {
            return;
        }

        ItemAffixes.Builder builder = affixes.toBuilder();
        List<DynamicHolder<Affix>> afxList = new ArrayList<>(affixes.keySet());

        for (DynamicHolder<Affix> affix : afxList) {
            builder.upgrade(affix, 1.5F);
        }

        setAffixes(stack, builder.build());
    }

    private static TranslatableContents copyContents(Component comp) {
        TranslatableContents tContents = (TranslatableContents) comp.getContents();
        Object[] args = tContents.getArgs();
        Object[] clone = Arrays.copyOf(args, args.length);
        return new TranslatableContents(tContents.getKey(), tContents.getFallback(), clone);
    }

    private static class ClientAccess {

        @Nullable
        private static Component getHiddenAffixName(Component currentName) {
            LocalPlayer player = Minecraft.getInstance().player;
            if (player != null && WorldTier.isTutorialActive(player)) {
                return Apotheosis.lang("text", "unidentified", currentName);
            }
            return null;
        }
    }

}

package dev.shadowsoffire.apotheosis.affix;

import java.util.Map;
import java.util.function.BiConsumer;

import javax.annotation.Nullable;

import dev.shadowsoffire.apotheosis.loot.LootCategory;
import dev.shadowsoffire.apotheosis.loot.LootRarity;
import dev.shadowsoffire.apothic_attributes.modifiers.StackAttributeModifiersEvent;
import dev.shadowsoffire.placebo.dynreg.DynamicHolder;
import it.unimi.dsi.fastutil.objects.ObjectArrayList;
import net.minecraft.core.BlockPos;
import net.minecraft.network.chat.Component;
import net.minecraft.network.chat.MutableComponent;
import net.minecraft.resources.Identifier;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.util.Mth;
import net.minecraft.world.InteractionResult;
import net.minecraft.world.damagesource.DamageSource;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.EquipmentSlot;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.entity.projectile.Projectile;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.context.UseOnContext;
import net.minecraft.world.level.LevelAccessor;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.storage.loot.LootContext;
import net.minecraft.world.phys.HitResult;
import net.neoforged.neoforge.common.util.AttributeTooltipContext;
import net.neoforged.neoforge.event.enchanting.GetEnchantmentLevelEvent;
import net.neoforged.neoforge.event.entity.living.LivingDropsEvent;

/**
 * An Affix Instance is a wrapper around the necessary parameters for all affix methods.
 * Prefer using this over directly invoking methods on {@link Affix}.
 *
 * @param affix  The affix this instance is for.
 * @param level  The level of the affix.
 * @param rarity The rarity of the source item.
 * @param stack  The source item stack.
 */
public record AffixInstance(DynamicHolder<Affix> affix, float level, DynamicHolder<LootRarity> rarity, ItemStack stack) {

    public LootCategory category() {
        return LootCategory.forItem(this.stack);
    }

    public boolean isValid() {
        return this.affix.isBound() && this.rarity.isBound();
    }

    /**
     * Resolves the underlying {@link #rarity}. Throws if unbound.
     */
    public LootRarity getRarity() {
        return this.rarity.get();
    }

    /**
     * Resolves the underlying {@link #affix}. Throws if unbound.
     */
    public Affix getAffix() {
        return this.affix.get();
    }

    /**
     * @see Affix#addModifiers(ItemStack, LootRarity, float, EquipmentSlot, BiConsumer)
     */
    public void addModifiers(StackAttributeModifiersEvent event) {
        this.getAffix().addModifiers(this, event);
    }

    /**
     * @see Affix#getDescription(ItemStack, LootRarity, float)
     */
    public MutableComponent getDescription(AttributeTooltipContext ctx) {
        return this.getAffix().getDescription(this, ctx);
    }

    /**
     * @see Affix#getAugmentingText(ItemStack, LootRarity, float)
     */
    public Component getAugmentingText(AttributeTooltipContext ctx) {
        return this.getAffix().getAugmentingText(this, ctx);
    }

    /**
     * @see Affix#getName(boolean)
     */
    public Component getName(boolean prefix) {
        return this.getAffix().getName(prefix);
    }

    /**
     * @see Affix#getDamageProtection(ItemStack, LootRarity, float, DamageSource)
     */
    public float getDamageProtection(DamageSource source) {
        return this.getAffix().getDamageProtection(this, source);
    }

    /**
     * @see Affix#getDamageBonus(ItemStack, LootRarity, float, MobType)
     */
    public float getDamageBonus(Entity entity) {
        return this.getAffix().getDamageBonus(this, entity);
    }

    /**
     * @see Affix#doPostAttack(ItemStack, LootRarity, float, LivingEntity, Entity)
     */
    public void doPostAttack(LivingEntity user, Entity target) {
        this.getAffix().doPostAttack(this, user, target);
    }

    /**
     * @see Affix#doPostHurt(ItemStack, LootRarity, float, LivingEntity, Entity)
     */
    public void doPostHurt(LivingEntity user, DamageSource source) {
        this.getAffix().doPostHurt(this, user, source);
    }

    /**
     * @see Affix#onProjectileFired(ItemStack, LootRarity, float, LivingEntity, Projectile)
     */
    public void onProjectileFired(LivingEntity user, Projectile proj) {
        this.getAffix().onProjectileFired(this, user, proj);
    }

    /**
     * @see Affix#onItemUse(ItemStack, LootRarity, float, UseOnContext)
     */
    @Nullable
    public InteractionResult onItemUse(UseOnContext ctx) {
        return this.getAffix().onItemUse(this, ctx);
    }

    /**
     * @see Affix#onShieldBlock(ItemStack, LootRarity, float, LivingEntity, DamageSource, float)
     */
    public float onShieldBlock(LivingEntity entity, DamageSource source, float amount) {
        return this.getAffix().onShieldBlock(this, entity, source, amount);
    }

