package dev.shadowsoffire.apotheosis.affix;

import java.util.LinkedHashSet;
import java.util.Map;
import java.util.Set;
import java.util.function.Consumer;
import java.util.stream.Collectors;

import org.apache.commons.lang3.tuple.Pair;
import org.spongepowered.include.com.google.common.base.Preconditions;

import com.mojang.serialization.Codec;
import com.mojang.serialization.codecs.RecordCodecBuilder;

import dev.shadowsoffire.apotheosis.Apotheosis;
import dev.shadowsoffire.apotheosis.affix.AffixBuilder.ValuedAffixBuilder;
import dev.shadowsoffire.apotheosis.loot.LootCategory;
import dev.shadowsoffire.apotheosis.loot.LootRarity;
import dev.shadowsoffire.apotheosis.tiers.WorldTier;
import dev.shadowsoffire.apothic_attributes.modifiers.StackAttributeModifiersEvent;
import dev.shadowsoffire.placebo.codec.PlaceboCodecs;
import dev.shadowsoffire.placebo.util.StepFunction;
import net.minecraft.ChatFormatting;
import net.minecraft.core.Holder;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.network.chat.Component;
import net.minecraft.network.chat.MutableComponent;
import net.minecraft.resources.Identifier;
import net.minecraft.world.entity.ai.attributes.Attribute;
import net.minecraft.world.entity.ai.attributes.AttributeModifier;
import net.minecraft.world.entity.ai.attributes.AttributeModifier.Operation;
import net.minecraft.world.item.ItemStack;
import net.neoforged.neoforge.common.util.AttributeTooltipContext;

/**
 * Helper class for affixes that modify attributes, as the apply method is the same for most of those.
 */
public class AttributeAffix extends Affix implements AttributeProvidingAffix {

    public static final Codec<AttributeAffix> CODEC = RecordCodecBuilder.create(inst -> inst
        .group(
            affixDef(),
            BuiltInRegistries.ATTRIBUTE.holderByNameCodec().fieldOf("attribute").forGetter(a -> a.attribute),
            PlaceboCodecs.enumCodec(Operation.class).fieldOf("operation").forGetter(a -> a.operation),
            LootRarity.mapCodec(StepFunction.CODEC).fieldOf("values").forGetter(a -> a.values),
            LootCategory.SET_CODEC.fieldOf("categories").forGetter(a -> a.categories))
        .apply(inst, AttributeAffix::new));

    protected final Holder<Attribute> attribute;
    protected final Operation operation;
    protected final Map<LootRarity, StepFunction> values;
    protected final Set<LootCategory> categories;

    protected transient final Map<LootRarity, ModifierInst> modifiers;

    public AttributeAffix(AffixDefinition def, Holder<Attribute> attr, Operation op, Map<LootRarity, StepFunction> values, Set<LootCategory> categories) {
        super(def);
        this.attribute = attr;
        this.operation = op;
        this.values = values;
        this.categories = categories;
        this.modifiers = values.entrySet().stream().map(entry -> Pair.of(entry.getKey(), new ModifierInst(attr, op, entry.getValue()))).collect(Collectors.toMap(Pair::getKey, Pair::getValue));
    }

    @Override
    public MutableComponent getDescription(AffixInstance inst, AttributeTooltipContext ctx) {
        return Component.empty();
    }

    @Override
    public Component getAugmentingText(AffixInstance inst, AttributeTooltipContext ctx) {
        ModifierInst modif = this.modifiers.get(inst.getRarity());
        double value = modif.valueFactory.get(inst.level());
        Attribute attr = this.attribute.value();

        MutableComponent comp;
        MutableComponent valueComp = attr.toValueComponent(this.operation, value, ctx.flag());
        ChatFormatting color = attr.getStyle(value > 0);

        if (value > 0.0D) {
            comp = Component.translatable("neoforge.modifier.plus", valueComp, Component.translatable(attr.getDescriptionId())).withStyle(color);
        }
        else {
            comp = Component.translatable("neoforge.modifier.take", valueComp, Component.translatable(attr.getDescriptionId())).withStyle(color);
        }

        if (modif.valueFactory.get(0) != modif.valueFactory.get(1)) {
            Component minComp = attr.toValueComponent(this.operation, modif.valueFactory.get(0), ctx.flag());
            Component maxComp = attr.toValueComponent(this.operation, modif.valueFactory.get(1), ctx.flag());
            comp.append(valueBounds(minComp, maxComp));
        }

        return comp;
    }

    @Override
    public void addModifiers(AffixInstance inst, StackAttributeModifiersEvent event) {
        LootCategory cat = inst.category();
        if (cat.isNone()) {
            Apotheosis.LOGGER.debug("Attempted to apply the attributes of affix {} on item {}, but it is not an affix-compatible item!", this.id(), inst.stack().getHoverName().getString());
            return;
        }
        ModifierInst modif = this.modifiers.get(inst.getRarity());
        if (modif.attr == null) {
            Apotheosis.LOGGER.debug("The affix {} has attempted to apply a null attribute modifier to {}!", this.id(), inst.stack().getHoverName().getString());
            return;
        }
        event.addModifier(this.attribute, modif.build(inst), cat.getSlots());
    }

    @Override
    public boolean canApplyTo(ItemStack stack, LootCategory cat, LootRarity rarity) {
        if (cat.isNone()) {
            return false;
        }
        return (this.categories.isEmpty() || this.categories.contains(cat)) && this.modifiers.containsKey(rarity);
    }

    @Override
    public void gatherModifierTooltips(AffixInstance inst, AttributeTooltipContext ctx, Consumer<Component> list) {
        ModifierInst modif = this.modifiers.get(inst.getRarity());
        Attribute attr = this.attribute.value();
        list.accept(attr.toComponent(modif.build(inst), ctx.flag()));
    }

    @Override
    public void skipModifierIds(AffixInstance inst, AttributeTooltipContext ctx, Consumer<Identifier> skip) {
        if (ctx.player() != null && WorldTier.isTutorialActive(ctx.player())) {
            skip.accept(inst.makeUniqueId());
        }
    }

    @Override
    public Codec<? extends Affix> getCodec() {
        return CODEC;
    }

    @Override
    public boolean isLevelIndependent(AffixInstance inst) {
        return this.values.get(inst.getRarity()).isConstant();
    }

    public static record ModifierInst(Holder<Attribute> attr, Operation op, StepFunction valueFactory) {

        public AttributeModifier build(AffixInstance inst) {
            return new AttributeModifier(inst.makeUniqueId(), this.valueFactory.get(inst.level()), this.op);
        }
    }

    public static class Builder extends ValuedAffixBuilder<Builder> {
        protected final Holder<Attribute> attribute;
        protected final Operation operation;
        protected final Set<LootCategory> categories = new LinkedHashSet<>();

        public Builder(Holder<Attribute> attribute, Operation operation) {
            this.attribute = attribute;
            this.operation = operation;
        }

        public Builder categories(LootCategory... cats) {
            for (LootCategory cat : cats) {
                this.categories.add(cat);
            }
            return this;
        }

        public AttributeAffix build() {
            Preconditions.checkArgument(!this.values.isEmpty());
            return new AttributeAffix(this.definition, this.attribute, this.operation, this.values, this.categories);
        }
    }

}

package dev.shadowsoffire.apotheosis.affix;

import java.util.function.Function;
import java.util.function.Predicate;
import java.util.stream.Stream;

import com.mojang.serialization.Codec;

import dev.shadowsoffire.placebo.dynreg.DynamicHolder;
import io.netty.buffer.ByteBuf;
import it.unimi.dsi.fastutil.objects.Object2FloatMap.Entry;
import it.unimi.dsi.fastutil.objects.Object2FloatOpenHashMap;
import it.unimi.dsi.fastutil.objects.ObjectSet;
import it.unimi.dsi.fastutil.objects.ObjectSets;
import net.minecraft.network.codec.ByteBufCodecs;
import net.minecraft.network.codec.StreamCodec;
import net.minecraft.world.item.ItemStack;

/**
 * Immutable data holder for the affixes on an {@link ItemStack}.
 * <p>
 * This object cannot be used to evaluate affixes, as evaluation requires context of the owning item stack.
 * Instead, use the map provided by {@link AffixHelper#getAffixes(ItemStack)}.
 */
public final class ItemAffixes {

    public static final Codec<ItemAffixes> CODEC = Codec.unboundedMap(AffixRegistry.INSTANCE.holderCodec(), Codec.floatRange(0, Affix.MAX_LEVEL))
        .xmap(Object2FloatOpenHashMap::new, Function.identity())
        .xmap(ItemAffixes::new, i -> i.affixes);

    public static final StreamCodec<ByteBuf, ItemAffixes> STREAM_CODEC = StreamCodec.composite(
        ByteBufCodecs.map(Object2FloatOpenHashMap::new, AffixRegistry.INSTANCE.holderStreamCodec(), ByteBufCodecs.FLOAT),
        ia -> ia.affixes,
        ItemAffixes::new);

    public static final ItemAffixes EMPTY = new ItemAffixes(new Object2FloatOpenHashMap<>());

    private final Object2FloatOpenHashMap<DynamicHolder<Affix>> affixes;

    private ItemAffixes(Object2FloatOpenHashMap<DynamicHolder<Affix>> affixes) {
        this.affixes = affixes;

        for (Entry<DynamicHolder<Affix>> entry : affixes.object2FloatEntrySet()) {
            float level = entry.getFloatValue();
            if (level < 0 || level > Affix.MAX_LEVEL) {
                throw new IllegalArgumentException("Affix " + entry.getKey() + " has invalid level " + level);
            }
        }
    }

    public float getLevel(DynamicHolder<Affix> key) {
        return this.affixes.getFloat(key);
    }

    public boolean isEmpty() {
        return this.affixes.isEmpty();
    }

    public int size() {
        return this.affixes.size();
    }

    public ObjectSet<Entry<DynamicHolder<Affix>>> entrySet() {
        return ObjectSets.unmodifiable(this.affixes.object2FloatEntrySet());
    }

    public ObjectSet<DynamicHolder<Affix>> keySet() {
        return ObjectSets.unmodifiable(this.affixes.keySet());
    }

    public Stream<Affix> liveAffixes() {
        return this.keySet().stream().filter(DynamicHolder::isBound).map(DynamicHolder::get);
    }

    @Override
    public boolean equals(Object other) {
        return this == other || other instanceof ItemAffixes iafxs && iafxs.affixes.equals(this.affixes);
    }

    @Override
    public int hashCode() {
        return this.affixes.hashCode();
    }

    @Override
    public String toString() {
        return "ItemAffixes{affixes=" + this.affixes + "}";
    }

    public Builder toBuilder() {
        return new Builder(this);
    }

    public static class Builder {

        Object2FloatOpenHashMap<DynamicHolder<Affix>> affixes = new Object2FloatOpenHashMap<>();

        public Builder(ItemAffixes base) {
            this.affixes.putAll(base.affixes);
        }

        public Builder put(DynamicHolder<Affix> affix, float level) {
            if (level < 0) {
                this.affixes.removeFloat(affix);
            }
            else {
                this.affixes.put(affix, Math.clamp(level, 0, Affix.MAX_LEVEL));
            }
            return this;
        }

        public Builder upgrade(DynamicHolder<Affix> affix, float level) {
            if (level > 0) {
                this.affixes.merge(affix, Math.clamp(level, 0, Affix.MAX_LEVEL), Float::max);
            }
            return this;
        }

        public Builder remove(DynamicHolder<Affix> affix) {
            this.affixes.removeFloat(affix);
            return this;
        }

        public Builder removeIf(Predicate<DynamicHolder<Affix>> filter) {
            this.affixes.keySet().removeIf(filter);
            return this;
        }

        public float getLevel(DynamicHolder<Affix> key) {
            return this.affixes.getFloat(key);
        }

        public boolean isEmpty() {
            return this.affixes.isEmpty();
        }

        public int size() {
            return this.affixes.size();
        }

        public ObjectSet<Entry<DynamicHolder<Affix>>> entrySet() {
            return ObjectSets.unmodifiable(this.affixes.object2FloatEntrySet());
        }

        public ObjectSet<DynamicHolder<Affix>> keySet() {
            return ObjectSets.unmodifiable(this.affixes.keySet());
        }

        public ItemAffixes build() {
            return new ItemAffixes(this.affixes);
        }

    }

}

package dev.shadowsoffire.apotheosis.affix.reforging;

import javax.annotation.Nullable;

import org.jetbrains.annotations.NotNull;

import dev.shadowsoffire.apotheosis.Apoth;
import dev.shadowsoffire.apotheosis.Apoth.Items;
import dev.shadowsoffire.apotheosis.Apoth.Menus;
import dev.shadowsoffire.apotheosis.loot.LootCategory;
import dev.shadowsoffire.apotheosis.loot.LootController;
import dev.shadowsoffire.apotheosis.loot.LootRarity;
import dev.shadowsoffire.apotheosis.loot.RarityRegistry;
import dev.shadowsoffire.apotheosis.tiers.GenContext;
import dev.shadowsoffire.apotheosis.util.ApothMiscUtil;
import dev.shadowsoffire.placebo.cap.InternalItemHandler;
import dev.shadowsoffire.placebo.menu.BlockEntityMenu;
import dev.shadowsoffire.placebo.util.EnchantmentUtils;
import net.minecraft.core.BlockPos;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.util.RandomSource;
import net.minecraft.world.Container;
import net.minecraft.world.entity.player.Inventory;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.inventory.DataSlot;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.levelgen.XoroshiroRandomSource;
import net.neoforged.neoforge.transfer.item.ItemResource;
import net.neoforged.neoforge.transfer.item.ResourceHandlerSlot;

public class ReforgingMenu extends BlockEntityMenu<ReforgingTableTile> {

    public static final String REFORGE_SEED = "apoth_reforge_seed";

    protected final Player player;
    protected InternalItemHandler itemInv = new InternalItemHandler(1);
    protected InternalItemHandler choicesInv = new InternalItemHandler(3);
    protected final RandomSource random = new XoroshiroRandomSource(0);
    protected final int[] costs = new int[3];
    protected int seed = -1;

    public ReforgingMenu(int id, Inventory inv, BlockPos pos) {
        super(Menus.REFORGING, id, inv, pos);
        this.player = inv.player;
        this.addSlot(new UpdatingSlot(this.itemInv, 0, 81, 62, stack -> !LootCategory.forItem(stack).isNone()){
            @Override
            public int getMaxStackSize() {
                return 1;
            }

            @Override
            public int getMaxStackSize(ItemStack pStack) {
                return 1;
            }
        });
        this.addSlot(new UpdatingSlot(this.tile.inv, 0, 39, 40, this.tile::isValidRarityMat));
        this.addSlot(new UpdatingSlot(this.tile.inv, 1, 123, 86, stack -> stack.is(Items.SIGIL_OF_REBIRTH)));
        this.addSlot(new ReforgingResultSlot(this.choicesInv, 0, 27, 135));
        this.addSlot(new ReforgingResultSlot(this.choicesInv, 1, 81, 135));
        this.addSlot(new ReforgingResultSlot(this.choicesInv, 2, 135, 135));
        this.addPlayerSlots(inv, 8, 184);

        this.mover.registerRule((stack, slot) -> slot >= this.playerInvStart && !LootCategory.forItem(stack).isNone(), 0, 1);
        this.mover.registerRule((stack, slot) -> slot >= this.playerInvStart && this.tile.isValidRarityMat(stack), 1, 2);
        this.mover.registerRule((stack, slot) -> slot >= this.playerInvStart && stack.is(Items.SIGIL_OF_REBIRTH), 2, 3);
        this.mover.registerRule((stack, slot) -> slot < this.playerInvStart, this.playerInvStart, this.hotbarStart + 9);
        this.registerInvShuffleRules();

        this.updateSeed();
        this.addDataSlot(DataSlot.shared(this.costs, 0));
        this.addDataSlot(DataSlot.shared(this.costs, 1));
        this.addDataSlot(DataSlot.shared(this.costs, 2));
    }

    @Override
    public void removed(Player pPlayer) {
        super.removed(pPlayer);
        this.clearContainer(pPlayer, this.itemInv);
    }

    protected void updateSeed() {
        int seed = this.player.getPersistentData().getIntOr(REFORGE_SEED, 0);
        if (seed == 0) {
            seed = this.player.getRandom().nextInt();
            this.player.getPersistentData().putInt(REFORGE_SEED, seed);
        }
        this.seed = seed;
    }

    public int getMatCount() {
        return this.getSlot(1).getItem().getCount();
    }

    public int getSigilCount() {
        return this.getSlot(2).getItem().getCount();
    }

    @Nullable
    public LootRarity getRarity() {
        ItemStack s = this.getSlot(1).getItem();
        if (s.isEmpty()) {
            return null;
        }
        return RarityRegistry.getMaterialRarity(s.getItem()).getOptional().orElse(null);
    }

    public int getSigilCost(int slot) {
        return this.costs[0] * ++slot;
    }

    public int getMatCost(int slot) {
        return this.costs[1] * ++slot;
    }

    public int getLevelCost(int slot) {
        return this.costs[2] * ++slot;
    }

    @Override
    public void slotsChanged(Container pContainer) {
        LootRarity rarity = this.getRarity();
        if (rarity != null) {
            ReforgingRecipe recipe = this.tile.getRecipeFor(rarity);
            if (recipe != null) {
                this.costs[0] = recipe.sigilCost();
                this.costs[1] = recipe.matCost();
                this.costs[2] = recipe.levelCost();
            }
        }

        ItemStack input = this.getSlot(0).getItem();
        for (int slot = 0; slot < 3; slot++) {
            if (!input.isEmpty() && rarity != null) {
                RandomSource rand = this.random;
                rand.setSeed(this.seed ^ BuiltInRegistries.ITEM.getKey(input.getItem()).hashCode() + slot);
                GenContext ctx = GenContext.forPlayer(rand, this.player);
                ItemStack output = LootController.createLootItem(input.copy(), rarity, ctx);
                this.choicesInv.set(slot, ItemResource.of(output), output.getCount());
            }
            else {
                this.choicesInv.set(slot, ItemResource.EMPTY, 0);
            }
        }

        super.slotsChanged(pContainer);
        this.tile.setChanged();
    }

    public class ReforgingResultSlot extends ResourceHandlerSlot {

        public ReforgingResultSlot(InternalItemHandler itemHandler, int index, int xPosition, int yPosition) {
            super(itemHandler, itemHandler::set, index, xPosition, yPosition);
        }

        @Override
        public boolean mayPlace(@NotNull ItemStack stack) {
            return false;
        }

        @Override
        public boolean mayPickup(Player playerIn) {
            ItemStack input = ReforgingMenu.this.getSlot(0).getItem();
            LootRarity rarity = ReforgingMenu.this.getRarity();
            ReforgingRecipe recipe = ReforgingMenu.this.tile.getRecipeFor(rarity);
            if (recipe == null || input.isEmpty()) {
                return false;
            }

            int sigils = ReforgingMenu.this.getSigilCount();
            int sigilCost = ReforgingMenu.this.getSigilCost(this.getSlotIndex());
            int mats = ReforgingMenu.this.getMatCount();
            int matCost = ReforgingMenu.this.getMatCost(this.getSlotIndex());
            int levels = ReforgingMenu.this.player.experienceLevel;
            int levelCost = ReforgingMenu.this.getLevelCost(this.getSlotIndex());

            if ((sigils < sigilCost || mats < matCost || levels < levelCost) && !ReforgingMenu.this.player.isCreative()) {
                return false;
            }

            return super.mayPickup(playerIn);
        }

        @Override
        public void onTake(Player player, ItemStack stack) {
            if (!player.level().isClientSide()) {
                ReforgingMenu.this.getSlot(0).set(ItemStack.EMPTY);
                if (!player.isCreative()) {
                    int sigilCost = ReforgingMenu.this.getSigilCost(this.getSlotIndex());
                    int matCost = ReforgingMenu.this.getMatCost(this.getSlotIndex());
                    int levelCost = ReforgingMenu.this.getLevelCost(this.getSlotIndex());
                    ItemStack mat = ReforgingMenu.this.getSlot(1).getItem();
                    mat.shrink(matCost);
                    ReforgingMenu.this.getSlot(1).set(mat);
                    ItemStack sigil = ReforgingMenu.this.getSlot(2).getItem();
                    sigil.shrink(sigilCost);
                    ReforgingMenu.this.getSlot(2).set(sigil);
                    EnchantmentUtils.chargeExperience(player, ApothMiscUtil.getExpCostForSlot(levelCost, this.getSlotIndex()));
                }
                player.getPersistentData().putInt(REFORGE_SEED, player.getRandom().nextInt());
                ReforgingMenu.this.updateSeed();
            }

            player.playSound(Apoth.Sounds.REFORGE_ITEM_REFORGED, 0.25F, player.getRandom().nextFloat() * 0.15F + 1F);
        }
    }

}

