import net.minecraft.world.item.ItemStack;

public class LootController {

    /**
     * @see {@link LootController#createLootItem(ItemStack, LootCategory, LootRarity, Random)}
     */
    public static ItemStack createLootItem(ItemStack stack, LootRarity rarity, GenContext ctx) {
        LootCategory cat = LootCategory.forItem(stack);
        if (cat.isNone()) {
            return stack;
        }
        return createLootItem(stack, cat, rarity, ctx);
    }

    static Random jRand = new Random();

    /**
     * Modifies an ItemStack with affixes of the target category and rarity.
     *
     * @param stack  The ItemStack.
     * @param cat    The LootCategory. Should be valid for the item being passed.
     * @param rarity The target Rarity.
     * @param rand   The Random
     * @return The modifed ItemStack (note the original is not preserved, but the stack is returned for simplicity).
     */
    public static ItemStack createLootItem(ItemStack stack, LootCategory cat, LootRarity rarity, GenContext ctx) {
        stack.set(Components.AFFIXES, ItemAffixes.EMPTY);
        AffixHelper.setRarity(stack, rarity);

        for (LootRule rule : rarity.getRules(cat)) {
            rule.execute(stack, rarity, ctx);
        }

        ItemAffixes loaded = stack.getOrDefault(Components.AFFIXES, ItemAffixes.EMPTY);
        if (loaded.size() == 0) {
            return stack; // TODO: Re-enable the hard error when we actually have affixes loaded.
            // throw new RuntimeException(String.format("Failed to locate any affixes for %s{%s} with category %s and rarity %s.", stack.getItem(), stack.getComponents(),
            // cat, rarity));
        }

        List<Affix> nameList = new ArrayList<>(loaded.size());
        for (DynamicHolder<Affix> a : loaded.keySet()) {
            nameList.add(a.get());
        }

        jRand.setSeed(ctx.rand().nextLong());
        Collections.shuffle(nameList, jRand);
        String key = nameList.size() > 1 ? "misc.apotheosis.affix_name.three" : "misc.apotheosis.affix_name.two";
        MutableComponent name = Component.translatable(key, nameList.get(0).getName(true), "", nameList.size() > 1 ? nameList.get(1).getName(false) : "").withStyle(Style.EMPTY.withColor(rarity.color()).withItalic(false));
        AffixHelper.setName(stack, name);
        stack.remove(Components.TOUCHED_BY_MALICE);

        return stack;
    }

    /**
     * Pulls a random LootRarity and AffixLootEntry, and generates an Affix Item
     *
     * @param rand   Random
     * @param rarity The rarity, or null if it should be randomly selected.
     * @param luck   The player's luck level
     * @param level  The world, since affix loot entries are per-dimension.
     * @return An affix item, or an empty ItemStack if no entries were available for the dimension.
     */
    public static ItemStack createRandomLootItem(GenContext ctx, @Nullable LootRarity rarity) {
        AffixLootEntry entry = AffixLootRegistry.INSTANCE.getRandomItem(ctx);
        if (entry == null) {
            return ItemStack.EMPTY;
        }
        if (rarity == null) {
            rarity = LootRarity.random(ctx, entry.rarities());
        }
        return createLootItem(entry.stack(), entry.getType(), rarity, ctx);
    }

    /**
     * Returns the pool of available affixes for an item, given the existing affixes present.
     *
     * @param stack  The item stack the affixes may be applied to
     * @param rarity The rarity of the item stack
     * @param type   The type of affix to target
     * @return A list of available affixes for the item. May be empty.
     */
    public static Stream<DynamicHolder<Affix>> getAvailableAffixes(ItemStack stack, LootRarity rarity, AffixType type) {
        LootCategory cat = LootCategory.forItem(stack);
        ItemAffixes current = stack.getOrDefault(Components.AFFIXES, ItemAffixes.EMPTY);
        return AffixHelper.byType(type).stream()
            .filter(a -> a.get().canApplyTo(stack, cat, rarity))
            .filter(a -> a.get().isCompatibleWith(current));
    }

    /**
     * Returns the pool of alternative affixes for an item, given the existing affixes present.
     * <p>
     * This method will make a copy of the item, remove the target affix from it, and then call {@link #getAvailableAffixes(ItemStack, LootRarity, AffixType)} for
     * the same affix type.
     *
     * @param stack  The item stack the affixes may be applied to
     * @param rarity The rarity of the item stack
     * @param type   The type of affix to target
     * @return A list of alternative affixes for the item. May be empty. The original affix will not be present in the list.
     */
    public static Stream<DynamicHolder<Affix>> getAlternativeAffixes(Player player, ItemStack stack, LootRarity rarity, DynamicHolder<Affix> affix) {
        ItemStack copy = stack.copy();
        ItemAffixes fixed = copy.getOrDefault(Components.AFFIXES, ItemAffixes.EMPTY).toBuilder().remove(affix).build();
        copy.set(Components.AFFIXES, fixed);
        return getAvailableAffixes(copy, rarity, affix.get().definition().type()).filter(a -> !a.equals(affix)).filter(hasPositiveWeight(player));
    }

    public static List<Weighted<Affix>> getWeightedAffixes(ItemStack stack, LootRarity rarity, AffixType type, GenContext ctx) {
        return getAvailableAffixes(stack, rarity, type).mapMulti(TieredWeights.wrapFilterHolders(ctx)).toList();
    }

    public static ItemStack createAffixItemFromPools(Set<DynamicHolder<LootRarity>> rarities, Set<DynamicHolder<AffixLootEntry>> entries, GenContext gCtx) {
        ItemStack stack;
        if (entries.isEmpty()) {
            LootRarity selectedRarity = LootRarity.randomFromHolders(gCtx, rarities);
            stack = LootController.createRandomLootItem(gCtx, selectedRarity);
        }
        else {
            Set<AffixLootEntry> resolved = entries.stream().filter(DynamicHolder::isBound).map(DynamicHolder::get).collect(Collectors.toSet());
            AffixLootEntry entry = AffixLootRegistry.INSTANCE.getRandomItem(gCtx, resolved::contains);
            if (entry == null) {
                return ItemStack.EMPTY;
            }

            LootRarity rarity;

            if (rarities.isEmpty()) {
                rarity = LootRarity.random(gCtx, entry.rarities());
            }
            else {
                rarity = LootRarity.randomFromHolders(gCtx, rarities);
            }

            stack = LootController.createLootItem(entry.stack(), rarity, gCtx);
        }
        return stack;
    }

    private static Predicate<DynamicHolder<Affix>> hasPositiveWeight(Player player) {
        WorldTier tier = WorldTier.getTier(player);
        float luck = player.getLuck();
        return a -> a.get().weights().getWeight(tier, luck) > 0;
    }

}

package dev.shadowsoffire.apotheosis.loot;

import java.util.List;

import com.mojang.serialization.Codec;
import com.mojang.serialization.codecs.RecordCodecBuilder;

import dev.shadowsoffire.apotheosis.Apoth.Components;
import dev.shadowsoffire.apotheosis.Apotheosis;
import dev.shadowsoffire.apotheosis.affix.Affix;
import dev.shadowsoffire.apotheosis.affix.AffixHelper;
import dev.shadowsoffire.apotheosis.affix.AffixRegistry;
import dev.shadowsoffire.apotheosis.affix.AffixType;
import dev.shadowsoffire.apotheosis.affix.ItemAffixes;
import dev.shadowsoffire.apotheosis.socket.SocketHelper;
import dev.shadowsoffire.apotheosis.tiers.GenContext;
import dev.shadowsoffire.placebo.codec.CodecMap;
import dev.shadowsoffire.placebo.codec.CodecProvider;
import net.minecraft.core.component.DataComponentPatch;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.resources.Identifier;
import net.minecraft.util.Mth;
import net.minecraft.util.random.Weighted;
import net.minecraft.util.random.WeightedRandom;
import net.minecraft.world.item.ItemStack;

public interface LootRule extends CodecProvider<LootRule> {

    public static final CodecMap<LootRule> CODEC = new CodecMap<>("Loot Rule");

    /**
     * Executes this loot rule, applying the changes to the passed item stack.
     *
     * @param stack  The item stack being modified.
     * @param rand   The random source.
     * @param rarity The current loot rarity (which owns this rule).
     * @param tier   The player's world tier.
     * @param luck   The player's luck.
     */
    void execute(ItemStack stack, LootRarity rarity, GenContext ctx);

    public static void initCodecs() {
        register("component", ComponentLootRule.CODEC);
        register("affix", AffixLootRule.CODEC);
        register("socket", SocketLootRule.CODEC);
        register("durability", DurabilityLootRule.CODEC);
        register("chanced", ChancedLootRule.CODEC);
        register("combined", CombinedLootRule.CODEC);
        register("select", SelectLootRule.CODEC);
    }

    private static void register(String id, Codec<? extends LootRule> codec) {
        CODEC.register(Apotheosis.loc(id), codec);
    }

    /**
     * Applies one or more data components to the target item stack.
     */
    public static record ComponentLootRule(DataComponentPatch components) implements LootRule {

        public static Codec<ComponentLootRule> CODEC = RecordCodecBuilder.create(inst -> inst.group(
            DataComponentPatch.CODEC.fieldOf("components").forGetter(ComponentLootRule::components))
            .apply(inst, ComponentLootRule::new));

        @Override
        public Codec<ComponentLootRule> getCodec() {
            return CODEC;
        }

        @Override
        public void execute(ItemStack stack, LootRarity rarity, GenContext ctx) {
            stack.applyComponents(this.components);
        }

    }

    /**
     * Applies one affix from the specified category to the item stack.
     */
    public static record AffixLootRule(AffixType type) implements LootRule {

        public static Codec<AffixLootRule> CODEC = RecordCodecBuilder.create(inst -> inst.group(
            AffixType.CODEC.fieldOf("affix_type").forGetter(AffixLootRule::type))
            .apply(inst, AffixLootRule::new));

        @Override
        public Codec<AffixLootRule> getCodec() {
            return CODEC;
        }

        @Override
        public void execute(ItemStack stack, LootRarity rarity, GenContext ctx) {
            List<Weighted<Affix>> available = LootController.getWeightedAffixes(stack, rarity, this.type, ctx);
            int weight = WeightedRandom.getTotalWeight(available, Weighted::weight);
            if (available.size() == 0 || weight == 0) {
                Identifier id = BuiltInRegistries.ITEM.getKey(stack.getItem());
                Apotheosis.LOGGER.error("Failed to execute AffixLootRule (no affixes available) {}/{}/{}/{}!", id, RarityRegistry.INSTANCE.getKey(rarity), this.type, LootCategory.forItem(stack));
                return;
            }
            Affix selected = WeightedRandom.getRandomItem(ctx.rand(), available, weight, Weighted::weight).get().value();
            ItemAffixes.Builder builder = stack.getOrDefault(Components.AFFIXES, ItemAffixes.EMPTY).toBuilder();
            builder.upgrade(AffixRegistry.INSTANCE.holder(selected), ctx.rand().nextFloat());
            AffixHelper.setAffixes(stack, builder.build());
        }
    }

    /**
     * Sets the number of sockets on the target item stack to a random value in the given range.
     * <p>
     * Will not reduce the number of sockets already on the item.
     */
    public static record SocketLootRule(int min, int max) implements LootRule {

        public static Codec<SocketLootRule> CODEC = RecordCodecBuilder.create(inst -> inst.group(
            Codec.intRange(0, 16).fieldOf("min").forGetter(SocketLootRule::min),
            Codec.intRange(1, 16).fieldOf("max").forGetter(SocketLootRule::max))
            .apply(inst, SocketLootRule::new));

        @Override
        public Codec<SocketLootRule> getCodec() {
            return CODEC;
        }

        @Override
        public void execute(ItemStack stack, LootRarity rarity, GenContext ctx) {
            int sockets = SocketHelper.getSockets(stack);
            int newSockets = ctx.rand().nextIntBetweenInclusive(this.min, this.max);
            if (newSockets > sockets) {
                SocketHelper.setSockets(stack, newSockets);
            }
        }

    }

    /**
     * Sets the {@link Components#DURABILITY_BONUS} value to a random value within a range.
     * <p>
     * Overwrites any existing durability bonus percentage.
     */
    public static record DurabilityLootRule(float min, float max) implements LootRule {

        public static Codec<DurabilityLootRule> CODEC = RecordCodecBuilder.create(inst -> inst.group(
            Codec.floatRange(0, 1).fieldOf("min").forGetter(DurabilityLootRule::min),
            Codec.floatRange(0, 1).fieldOf("max").forGetter(DurabilityLootRule::max))
            .apply(inst, DurabilityLootRule::new));

        @Override
        public Codec<DurabilityLootRule> getCodec() {
            return CODEC;
        }

        @Override
        public void execute(ItemStack stack, LootRarity rarity, GenContext ctx) {
            stack.set(Components.DURABILITY_BONUS, Mth.lerp(ctx.rand().nextFloat(), this.min, this.max));
        }

    }

    /**
     * Wraps a loot rule with a random chance applied to it.
     */
    public static record ChancedLootRule(float chance, LootRule rule) implements LootRule {

        public static Codec<ChancedLootRule> CODEC = RecordCodecBuilder.create(inst -> inst
            .group(
                Codec.FLOAT.fieldOf("chance").forGetter(ChancedLootRule::chance),
                LootRule.CODEC.fieldOf("rule").forGetter(ChancedLootRule::rule))
            .apply(inst, ChancedLootRule::new));

        @Override
        public Codec<ChancedLootRule> getCodec() {
            return CODEC;
        }

        @Override
        public void execute(ItemStack stack, LootRarity rarity, GenContext ctx) {
            if (ctx.rand().nextFloat() <= this.chance) {
                this.rule.execute(stack, rarity, ctx);
            }
        }

    }

    /**
     * Wraps multiple loot rules into a single loot rule.
     * Can be combined with {@link ChancedLootRule} to bind multiple rules to the same chance.
     */
    public static record CombinedLootRule(List<LootRule> rules) implements LootRule {

        public static Codec<CombinedLootRule> CODEC = RecordCodecBuilder.create(inst -> inst
            .group(
                LootRule.CODEC.listOf().fieldOf("rules").forGetter(CombinedLootRule::rules))
            .apply(inst, CombinedLootRule::new));

        @Override
        public Codec<CombinedLootRule> getCodec() {
            return CODEC;
        }

        @Override
        public void execute(ItemStack stack, LootRarity rarity, GenContext ctx) {
            for (LootRule rule : this.rules) {
                rule.execute(stack, rarity, ctx);
            }
        }

    }

    /**
     * Implements a select loot rule, which rolls a chance and picks one rule if true, and another if false.
     */
    public static record SelectLootRule(float chance, LootRule ifTrue, LootRule ifFalse) implements LootRule {

        public static Codec<SelectLootRule> CODEC = RecordCodecBuilder.create(inst -> inst
            .group(
                Codec.FLOAT.fieldOf("chance").forGetter(SelectLootRule::chance),
                LootRule.CODEC.fieldOf("if_true").forGetter(SelectLootRule::ifTrue),
                LootRule.CODEC.fieldOf("if_false").forGetter(SelectLootRule::ifFalse))
            .apply(inst, SelectLootRule::new));

        @Override
        public Codec<SelectLootRule> getCodec() {
            return CODEC;
        }

        @Override
        public void execute(ItemStack stack, LootRarity rarity, GenContext ctx) {
            if (ctx.rand().nextFloat() <= this.chance) {
                this.ifTrue.execute(stack, rarity, ctx);
            }
            else {
                this.ifFalse.execute(stack, rarity, ctx);
            }
        }

    }

}
